export interface AccordionProps extends HTMLAttributes<HTMLDivElement> {
  /** Allow multiple items open simultaneously */
  multiple?: boolean;
  /** Initial open item(s) for uncontrolled usage */
  defaultOpen?: string | number | (string | number)[];
  /**
   * Controlled open items. When provided, open/close is driven externally.
   * Use with onExpandedChange.
   */
  expanded?: string | number | (string | number)[];
  /**
   * Called when an item is toggled.
   * Receives the full array of currently open item values.
   * Also fires in uncontrolled mode as a change observer.
   */
  onExpandedChange?: (values: (string | number)[]) => void;
  /**
   * When true each item renders as an elevated card (shadow, no border).
   * When false (default) each item has a 1px border, no shadow.
   * Matches tiket.design "Inside Card: True / False" variants.
   */
  insideCard?: boolean;
  children?: ReactNode;
}

export interface AccordionItemProps extends HTMLAttributes<HTMLDivElement> {
  value: string | number;
  disabled?: boolean;
  children?: ReactNode;
}

export interface AccordionTriggerProps extends HTMLAttributes<HTMLButtonElement> {
  value: string;
  disabled?: boolean;
  children?: ReactNode;
}

export interface AccordionContentProps extends HTMLAttributes<HTMLDivElement> {
  value: string;
  children?: ReactNode;
}

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant;
  dot?: boolean;
  count?: boolean;
  loading?: boolean;
  disabled?: boolean;
  children?: ReactNode;
}

export interface BannerProps extends HTMLAttributes<HTMLDivElement> {
  variant?: BannerVariant;
  /**
   * Layout mode.
   * - `sectional` (default): 8px radius, optional × dismiss button.
   * - `full-width`: 0px radius, chevron on right, entire banner is tappable via `onClick`.
   */
  layout?: BannerLayout;
  title?: string;
  description?: ReactNode;
  icon?: ReactNode;
  /** Show × dismiss button. Only applies to `sectional` layout. */
  dismissible?: boolean;
  onDismiss?: () => void;
  /** Text link CTA shown below description */
  action?: { label: string; onClick: () => void };
  children?: ReactNode;
}

export interface BannerGradientPageControl {
  /** Total number of pages */
  count: number;
  /** Currently active page index (0-based) */
  current: number;
  /** Dot color variant (default: 'white') */
  variant?: 'white' | 'blue';
}

export interface BannerGradientProps extends HTMLAttributes<HTMLDivElement> {
  /** Shape and size variant (default: 'big-rounded') */
  variant?: BannerGradientVariant;
  /** Gradient color (default: 'violet') */
  gradient?: BannerGradientGradient;
  /** Left icon — unremovable per spec; strongly recommended */
  icon?: ReactNode;
  /** Main text content — body 3 style. Supports ReactNode for bold+regular mixed content. */
  text: ReactNode;
  /** Use bold weight instead of semibold (default: false) */
  bold?: boolean;
  /** Countdown slot — small variant only */
  countdown?: ReactNode;
  /**
   * Show right chevron icon.
   * Default: true for 'small', false for big variants.
   */
  showChevron?: boolean;
  /** Page indicator dots — big-rounded and big-rectangle only */
  pageControl?: BannerGradientPageControl;
}

export interface BannerInfoProps extends HTMLAttributes<HTMLDivElement> {
  /** Card title — body 1 bold */
  title?: string;
  /** Card body text — body 2 regular. Supports ReactNode for mixed content. */
  description: ReactNode;
  /** Text link CTA shown below description — body 3 bold, activity color */
  action?: { label: string; onClick: () => void };
  /** Callback for the × close button. When provided, the button is rendered. */
  onClose?: () => void;
  /** Left illustration slot — 80×80 container */
  illustration?: ReactNode;
  /**
   * Decorative top-right super graphic — 96×93 absolute container.
   * Behind the close button. Purely visual.
   */
  superGraphic?: ReactNode;
}

export interface BottomSheetIconAction {
  icon: ReactNode;
  label: string;
  onClick: () => void;
}

export interface BottomSheetProps
  extends
    HTMLAttributes<HTMLDivElement>,
    FqSlotCustomization<
      | 'root'
      | 'backdrop'
      | 'handle'
      | 'handleBar'
      | 'image'
      | 'header'
      | 'title'
      | 'closeButton'
      | 'actions'
      | 'action'
      | 'iconAction'
      | 'body'
    > {
  /** Portal target. Prefer a callback when the target is created after mount. */
  container?: FqPortalContainer;
  open: boolean;
  onClose: () => void;
  title?: string;
  /** Show the drag handle bar (default: true) */
  handle?: boolean;
  /** Dismiss when clicking the backdrop (default: true) */
  backdropDismiss?: boolean;
  /** Text link action shown in the header right side */
  action?: { label: string; onClick: () => void };
  /** Up to 2 icon-button actions shown in the header right side */
  iconActions?: BottomSheetIconAction[];
  /** Image slot rendered between handle and title (With Image variant) */
  image?: ReactNode;
  /** Override the maximum height of the sheet (default: '90vh') */
  maxHeight?: string;
  /**
   * Disable portal rendering. When false (default), the sheet renders into
   * document.body so it is never clipped by overflow:hidden ancestors.
   */
  disablePortal?: boolean;
  children?: ReactNode;
}

export interface ButtonProps
  extends
    ButtonHTMLAttributes<HTMLButtonElement>,
    FqSlotCustomization<'root' | 'content' | 'spinner'> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  fullWidth?: boolean;
  startIcon?: ReactNode;
  endIcon?: ReactNode;
  iconOnly?: boolean;
  children?: ReactNode;
}

export interface CheckboxProps
  extends
    Omit<InputHTMLAttributes<HTMLInputElement>, 'size'>,
    FormFieldProps,
    FqSlotCustomization<'root' | 'label' | 'input' | 'helperText'> {
  indeterminate?: boolean;
  readOnly?: boolean;
}

export interface CheckboxGroupProps
  extends
    HTMLAttributes<HTMLFieldSetElement>,
    FormFieldProps,
    FqSlotCustomization<
      'root' | 'legend' | 'required' | 'items' | 'helperText'
    > {
  required?: boolean;
  disabled?: boolean;
}

export interface ChipsProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  active?: boolean;
  error?: boolean;
  invert?: boolean;
  startIcon?: ReactNode;
  endIcon?: ReactNode;
  badge?: ReactNode;
  /** Called when the dismiss (×) button is clicked or activated via keyboard. */
  onDismiss?: () => void;
  children?: ReactNode;
}

export interface CoachmarkProps extends HTMLAttributes<HTMLDivElement> {
  open: boolean;
  title: string;
  body: ReactNode;
  /** Optional illustration shown above the title */
  illustration?: ReactNode;
  step?: number;
  totalSteps?: number;
  nextLabel?: string;
  doneLabel?: string;
  skipLabel?: string;
  onNext?: () => void;
  onSkip?: () => void;
  onDone?: () => void;
  placement?: CoachmarkPlacement;
  /** The target element to anchor the coachmark to */
  children?: ReactNode;
}

export interface CountdownProps extends Omit<
  HTMLAttributes<HTMLSpanElement>,
  'children'
> {
  /** Target date/time to count down to */
  targetDate?: Date;
  /** Remaining seconds (alternative to targetDate) */
  seconds?: number;
  variant?: CountdownVariant;
  /** Display mode: boxed (pill segments), unboxed (plain text), unboxed-small (plain text, smaller) */
  display?: CountdownDisplay;
  /** Show hours segment */
  showHours?: boolean;
  /** Show centiseconds (.xx) after seconds */
  showMilliseconds?: boolean;
  onExpire?: () => void;
}

export interface DialogProps
  extends
    Pick<AriaAttributes, 'aria-label' | 'aria-labelledby' | 'aria-describedby'>,
    FqSlotCustomization<
      | 'paper'
      | 'backdrop'
      | 'title'
      | 'heading'
      | 'closeButton'
      | 'content'
      | 'actions'
    > {
  /** Portal target. Prefer a callback when the target is created after mount. */
  container?: FqPortalContainer;
  /** Render inline. Inline overlays remain subject to ancestor clipping/stacking. */
  disablePortal?: boolean;
  open: boolean;
  /** Called when the dialog requests to close (Escape or backdrop click). */
  onClose?: () => void;
  /** Heading text or element rendered in the header area. */
  title?: ReactNode;
  /** Main content of the dialog. */
  children?: ReactNode;
  /** Bottom action area — typically Button(s). */
  actions?: ReactNode;
  /** Controls the width of the dialog paper. Default: 'md'. */
  size?: DialogSize;
  /**
   * When true, clicking the backdrop does not call onClose.
   * Escape key still works.
   */
  disableBackdropClick?: boolean;
  className?: string;
  style?: CSSProperties;
}

export interface FieldProps extends FqSlotCustomization<
  'root' | 'label' | 'required' | 'description' | 'error'
> {
  className?: string;
  style?: CSSProperties;
  id?: string;
  label?: ReactNode;
  description?: ReactNode;
  error?: ReactNode;
  required?: boolean;
  children: ReactNode;
}

export interface IconBaseProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Icon size token → actual px:
   * xs=12 | sm=16 | md=20 | lg=24 (default) | xl=32 | 2xl=40 | 3xl=48
   */
  size?: IconSize;
  /**
   * Semantic color token. Defaults to `inherit` (uses the parent's color).
   */
  color?: IconColor;
  /** Accessible label. When provided: role="img". When omitted: aria-hidden="true". */
  'aria-label'?: string;
  /** The SVG icon element (e.g. a lucide-react component or inline <svg>). */
  children: ReactNode;
}

export interface IconButtonProps extends Omit<
  ButtonBaseProps<'button'>,
  'component' | 'color' | 'children'
> {
  /** Visual variant */
  variant?: IconButtonVariant;
  /** Button + icon size */
  size?: IconButtonSize;
  /** Semantic color for the icon (and tinted bg in filled/outlined variants) */
  color?: IconColor;
  /** Accessible label — required for icon-only controls */
  'aria-label': string;
  /** The SVG icon to render (lucide-react or inline <svg>) */
  children: ReactNode;
}

export interface InputProps
  extends
    InputHTMLAttributes<HTMLInputElement>,
    FormFieldProps,
    FqSlotCustomization<
      | 'root'
      | 'container'
      | 'inner'
      | 'row'
      | 'label'
      | 'input'
      | 'helperText'
      | 'prefix'
      | 'startIcon'
      | 'endIcon'
      | 'clearButton'
      | 'required'
    > {
  /** Text prefix shown before input when focused/filled (e.g. "IDR" for currency) */
  prefix?: string;
  /** Icon on the left side inside the container */
  startIcon?: ReactNode;
  /** Icon on the right side inside the container (overrides built-in clear button) */
  endIcon?: ReactNode;
  /** When provided, a clear (✕) button appears inside the field while focused and value is non-empty */
  onClear?: () => void;
}

export interface LabelProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: LabelVariant;
  size?: LabelSize;
  startIcon?: ReactNode;
  loading?: boolean;
  disabled?: boolean;
  /**
   * Countdown slot — rendered after text.
   * Pass a `<Countdown display="unboxed-small" />` for spec-aligned output.
   */
  countdown?: ReactNode;
  /**
   * Called when the embedded countdown expires.
   * Wire this to the `onExpire` prop of the Countdown you pass as `countdown`.
   */
  onExpire?: () => void;
  children?: ReactNode;
}

export interface NavItemProps {
  value: string;
  label: string;
  icon: ReactNode;
  badge?: ReactNode;
  disabled?: boolean;
}

export interface NavigationBottomProps extends HTMLAttributes<HTMLElement> {
  items: NavItemProps[];
  value: string;
  onValueChange: (value: string) => void;
}

export type SnackbarPlacement = {
  vertical?: 'top' | 'bottom';
  horizontal?: 'left' | 'center' | 'right';
};

export interface SnackbarProps extends FqSlotCustomization<
  'root' | 'content' | 'message' | 'action'
> {
  /** Portal target. Prefer a callback when the target is created after mount. */
  container?: FqPortalContainer;
  /** Render inline. Inline overlays remain subject to ancestor clipping/stacking. */
  disablePortal?: boolean;
  open: boolean;
  message: ReactNode;
  /** Visual intent. Default: 'default' (neutral dark). */
  variant?: SnackbarVariant;
  /** Optional action element shown on the right (e.g. an Undo button). */
  action?: ReactNode;
  /** Milliseconds before auto-hide. Pass null to disable. Default: 4000. */
  autoHideDuration?: number | null;
  /** Called when the snackbar requests to close. */
  onClose?: (
    event: SyntheticEvent | Event,
    reason: SnackbarCloseReason,
  ) => void;
  /** Screen position. Default: bottom-center. */
  anchorOrigin?: SnackbarPlacement;
  className?: string;
  style?: CSSProperties;
}

export interface TabsProps extends HTMLAttributes<HTMLDivElement> {
  /** Controlled selected tab value */
  value?: string | number;
  /** Default selected tab for uncontrolled usage */
  defaultValue?: string | number;
  onValueChange?: (value: string | number) => void;
  /**
   * How arrow-key navigation activates tabs.
   * - 'auto' (default): focus + immediately selects the tab (ARIA recommended).
   * - 'manual': focus only — user must press Enter/Space to activate.
   */
  activationMode?: 'auto' | 'manual';
  /** Dark/inverted surface variant */
  invert?: boolean;
  children?: ReactNode;
}

export interface TabListProps extends HTMLAttributes<HTMLDivElement> {
  /** Distribute tabs equally across full width (Equally Distributed: True per spec) */
  equallyDistributed?: boolean;
  children?: ReactNode;
}

export interface TabProps extends HTMLAttributes<HTMLButtonElement> {
  value: string | number;
  disabled?: boolean;
  icon?: ReactNode;
  badge?: ReactNode;
  children?: ReactNode;
}

export interface TabPanelProps extends HTMLAttributes<HTMLDivElement> {
  value: string | number;
  children?: ReactNode;
}

export interface TooltipProps
  extends
    Omit<HTMLAttributes<HTMLDivElement>, 'content' | 'onOpen' | 'onClose'>,
    FqSlotCustomization<'root' | 'content' | 'arrow'> {
  content: ReactNode;
  placement?: TooltipPlacement;
  /** Where the arrow sits along the tooltip edge. Default: 'center'. */
  arrowAlignment?: TooltipArrowAlignment;
  /** Delay before showing in ms. Default: 300. */
  enterDelay?: number;
  /** @deprecated Use enterDelay instead. */
  delayMs?: number;
  /** Delay before hiding in ms. Default: 0. */
  leaveDelay?: number;
  /** Use body3-bold font weight (spec: body3-regular default). */
  bold?: boolean;
  /** Show or hide the arrow. Default: true. */
  arrow?: boolean;
  /** Override the max-width of the tooltip bubble. */
  maxWidth?: number | string;
  /** Controlled open state. When provided, open/close is driven externally. */
  open?: boolean;
  /** Called when the tooltip requests to open (uncontrolled: also updates internal state). */
  onOpen?: () => void;
  /** Called when the tooltip requests to close (uncontrolled: also updates internal state). */
  onClose?: () => void;
  /** Disable hover (mouseenter/mouseleave) trigger. Default: false. */
  disableHoverListener?: boolean;
  /** Disable keyboard focus/blur trigger. Default: false. */
  disableFocusListener?: boolean;
  /** Disable touch (touchstart/touchend) trigger. Default: false. */
  disableTouchListener?: boolean;
  children: ReactElement;
}
